public static int find(int[] a, int x) {
    return find0(a, x, 0, a.length - 1);
}

public static int find0(int[] a, int x, int lo, int hi) {
    if (lo > hi)
        return -1;

    int mid = (lo + hi) / 2;

    if (a[mid] == x)
        return mid;

    if (x > a[mid])
        return find0(a, x, mid + 1, hi);

    return find0(a, x, lo, mid - 1);
}
```
